import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { ubicacionesData } from "../data/ubicacionesData";


/* ================================
   COMPONENTE 1: Administrativas
   ================================ */
export function Administrativas() {
  const navigate = useNavigate();
  const chatEndRef = useRef(null);

  const [messages, setMessages] = useState([
    { type: "bot", content: "options", timestamp: new Date() },
  ]);
  const [inputValue, setInputValue] = useState("");
  const [showMoreOptions, setShowMoreOptions] = useState(false);

  const predefinedOptions = [
    { img: "/item-chat.png", text: "Kardex" },
    { img: "/item-chat.png", text: "Constancia" },
    { img: "/item-chat.png", text: "Titulacion" },
    { img: "/item-chat.png", text: "Creditos" },
    { img: "/item-chat.png", text: "Mas opciones..." },
  ];

  const additionalOptions = [
    { img: "/item-chat.png", text: "Historial Academico" },
    { img: "/item-chat.png", text: "Pagos y Finanzas" },
    { img: "/item-chat.png", text: "Horarios" },
  ];

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleOptionClick = (option) => {
    const userMessage = { type: "user", content: option, timestamp: new Date() };

    const botInfo = {
      type: "bot",
      content: `Para el proceso de ${option.toLowerCase()} se tiene que hacer lo siguiente:

1.- Ingresa al SIM con tu número de control y contraseña.
2.- Dirígete al módulo correspondiente.
3.- Ahí te aparecerá una tabla con las opciones relacionadas, selecciona la que necesites.
4.- Por último, sigue las instrucciones mostradas.`,
      timestamp: new Date(),
    };

    const botActions = {
      type: "bot",
      content:
        'Si quiere cambiar de proceso, presione el botón de opciones en el área de texto.',
      timestamp: new Date(),
    };

    if (option === "Mas opciones...") {
      setShowMoreOptions(true);
      setMessages((prevMessages) => [
        ...prevMessages,
        userMessage,
        { type: "bot", content: "moreOptions", timestamp: new Date() },
        {
          type: "bot",
          content:
            "Si no se encuentra la opción que usted busca, favor de escribirla en el chat.",
          timestamp: new Date(),
        },
      ]);
    } else {
      setMessages((prevMessages) => [...prevMessages, userMessage, botInfo, botActions]);
    }
  };

  const simulateBotResponse = (userInput, currentMessages) => {
    const input = userInput.toLowerCase();
    const botResponse = { type: "bot", content: "", timestamp: new Date() };

    if (input.includes("evaluacion") || input.includes("profesor")) {
      botResponse.content = `Para el proceso de evaluación de docentes se tiene que hacer lo siguiente:

1.- Ingresa al SIM con tu número de control y contraseña.
2.- Dirígete al módulo de evaluaciones y encuestas.
3.- Ahí te aparecerá una tabla con todas las evaluaciones posibles, selecciona la que necesites.
4.- Por último, contesta todas las preguntas.`;

      setMessages((prevMessages) => [
        ...prevMessages,
        botResponse,
        {
          type: "bot",
          content:
            'Si quiere cambiar de proceso, presione el botón de opciones en el área de texto.',
          timestamp: new Date(),
        },
      ]);
      return;
    }

    if (input.includes("kardex")) {
      botResponse.content = `El Kardex es un documento que muestra tu historial académico completo.`;
    } else if (input.includes("constancia")) {
      botResponse.content = `La constancia de estudios se solicita en servicios escolares.`;
    } else if (input.includes("titulacion")) {
      botResponse.content = `El proceso de titulación implica completar créditos y requisitos.`;
    } else if (input.includes("credito")) {
      botResponse.content = `Los créditos complementarios se registran en actividades culturales o académicas.`;
    } else if (input.includes("historial")) {
      botResponse.content = `El historial académico se descarga desde el portal del SIM.`;
    } else if (input.includes("pago")) {
      botResponse.content = `Los pagos se realizan en caja o por transferencia.`;
    } else if (input.includes("horario")) {
      botResponse.content = `Tu horario actual se encuentra en el portal del SIM.`;
    } else {
      botResponse.content = `Has escrito: "${userInput}". ¿Podrías darme más detalles?`;
    }

    setMessages((prevMessages) => [...prevMessages, botResponse]);
  };

  const handleSendMessage = () => {
    if (inputValue.trim()) {
      const newMessages = [
        ...messages,
        { type: "user", content: inputValue, timestamp: new Date() },
      ];
      setMessages(newMessages);
      setInputValue("");
      setTimeout(() => simulateBotResponse(inputValue, newMessages), 500);
    }
  };

  const handleProcessChange = () => {
    setShowMoreOptions(true);
    setMessages((prevMessages) => [
      ...prevMessages,
      { type: "bot", content: "options", timestamp: new Date() },
    ]);
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage();
  };

  return (
    <div className="procesos-container">
      <header className="procesos-header">
        <div className="procesos-header-left">
          <button className="procesos-name-button" onClick={() => navigate("/")}>
            <i className="bi bi-chevron-double-left"></i>
          </button>
          <h1>TalkinPon</h1>
        </div>
        <div className="procesos-title-logo">
          <h2>Procesos Administrativos</h2>
        </div>
        <div className="procesos-heade-logo">
          <img src="/logo-app.png" alt="Logo" />
        </div>
      </header>

      <div className="procesos-chat-area">
        {messages.map((message, index) => (
          <div key={index} className={`procesos-chat-message ${message.type}`}>
            <div className="procesos-avatar">
              <img
                src={message.type === "bot" ? "/logo-app.png" : "/img-user.png"}
                alt={message.type === "bot" ? "Bot" : "User"}
              />
            </div>

            <div className="procesos-message-with-actions">
              {message.content === "options" ? (
                <div className="procesos-options-box">
                  <h3>Elige una opción:</h3>
                  {predefinedOptions.map((option, idx) => (
                    <button key={idx} onClick={() => handleOptionClick(option.text)}>
                      <img src={option.img} alt={option.text} className="procesos-option-img" />
                      <span>{option.text}</span>
                    </button>
                  ))}
                </div>
              ) : message.content === "moreOptions" ? (
                <div className="procesos-options-box">
                  <h3>Más opciones disponibles:</h3>
                  {additionalOptions.map((option, idx) => (
                    <button key={idx} onClick={() => handleOptionClick(option.text)}>
                      <img src={option.img} alt={option.text} className="procesos-option-img" />
                      <span>{option.text}</span>
                    </button>
                  ))}
                </div>
              ) : (
                <div className={`procesos-message-box ${message.type}`}>
                  <p>{message.content}</p>
                </div>
              )}
            </div>
          </div>
        ))}
        <div ref={chatEndRef}></div>
      </div>

      <div className="procesos-input-area border-top">
        <div className="procesos-input-group">
          <input
            type="text"
            className="procesos-form-control"
            placeholder="¿Qué te gustaría saber ...?"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={handleKeyPress}
          />
          <button className="procesos-btn" onClick={handleSendMessage}>
            <i className="bi bi-send-fill"></i>
          </button>
        </div>
        <div className="procesos-div-cambio">
          <button className="procesos-btn-cambio" onClick={handleProcessChange}>
            <i className="bi bi-menu-up"></i>
          </button>
        </div>
      </div>
    </div>
  );
}

/* ================================
   COMPONENTE 2: Ubicaciones
   ================================ */
export function Ubicaciones() {
  const [messages, setMessages] = useState([
    { type: "bot", content: "¿Qué edificio o salón te gustaría saber su ubicación?" },
  ]);
  const navigate = useNavigate();
  const [inputValue, setInputValue] = useState("");
  const [showMap, setShowMap] = useState(false);
  const [animateMap, setAnimateMap] = useState(false);
  const chatEndRef = useRef(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  useEffect(() => {
    if (showMap) document.body.classList.add("map-open");
    else document.body.classList.remove("map-open");
  }, [showMap]);

  const generateBotResponse = (userInput) => {
    const input = userInput.toUpperCase();
    const ubicacion = ubicacionesData.find((u) => u.id === input);

    if (ubicacion) {
      return [
        { type: "bot", content: ubicacion.texto },
        { type: "bot", content: "building_image", buildingImage: ubicacion.imagen },
        { type: "bot", content: "Si ocupa saber otra ubicación, escríbela o consulta el mapa." },
      ];
    }

    return [
      { type: "bot", content: "Lo siento, no tengo información sobre esa ubicación." },
    ];
  };

  const handleSendMessage = () => {
    if (!inputValue.trim()) return;
    const userMessage = { type: "user-ub", content: inputValue };
    const botResponse = generateBotResponse(inputValue);
    setMessages((prev) => [...prev, userMessage, ...botResponse]);
    setInputValue("");
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage();
  };

  const toggleMap = () => {
    if (showMap) {
      setAnimateMap(false);
      setTimeout(() => setShowMap(false), 300);
    } else {
      setShowMap(true);
      setTimeout(() => setAnimateMap(true), 10);
    }
  };

  const handleMapButtonClick = (id) => {
    const botResponse = generateBotResponse(id);
    const userMessage = { type: "user-ub", content: id };
    setMessages((prev) => [...prev, userMessage, ...botResponse]);
  };

  return (
    <div className="ubicaciones-container">
      <header className="ubicaciones-header">
        <div className="procesos-header-left">
          <button className="ubicaciones-name-button" onClick={() => navigate("/")}>
            <i className="bi bi-chevron-double-left"></i>
          </button>
          <h1>TalkinPon</h1>
        </div>
        <div className="ubicaciones-title-logo">
          <h2>Ubicaciones</h2>
        </div>
        <div className="ubicaciones-heade-logo">
          <button onClick={toggleMap} className="ubicaciones-toggle-btn" title="Mostrar mapa">
            <i className="bi bi-map-fill"></i>
          </button>
        </div>
        <div className="ubicaciones-heade-logo">
          <img src="/logo-app.png" alt="Logo" />
        </div>
      </header>

      <div className="main-content">
        <div className="chat-area-ub">
          {messages.map((message, idx) => (
            <div key={idx} className={`message-row-ub ${message.type}`}>
              <img
                src={message.type === "bot" ? "/logo-app.png" : "/img-user.png"}
                alt={message.type === "bot" ? "Bot" : "Usuario"}
                className="avatar-ub"
              />
              <div className="message-with-actions">
                <div className={`message-box-ub ${message.type}`}>
                  {message.content === "building_image" ? (
                    <img src={message.buildingImage} alt="Edificio" className="building-image" />
                  ) : (
                    <p>{message.content}</p>
                  )}
                </div>
              </div>
            </div>
          ))}
          <div ref={chatEndRef}></div>
        </div>
      </div>

      <div className="ubicaciones-input-area border-top">
        <div className="ubicaciones-input-group">
          <input
            type="text"
            className="ubicaciones-form-control"
            placeholder="¿Qué te gustaría saber ...?"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyPress={handleKeyPress}
          />
          <button className="ubicaciones-btn" onClick={handleSendMessage}>
            <i className="bi bi-send-fill"></i>
          </button>
        </div>
      </div>

      {showMap && (
        <>
          <div className="map-overlay"></div>
          <div className={`map-area ${animateMap ? "map-open" : "map-close"}`}>
            <div className="map-header">
              <h3>Mapa del Campus</h3>
              <button
                onClick={() => {
                  setAnimateMap(false);
                  setTimeout(() => setShowMap(false), 300);
                }}
                className="close-map-btn"
              >
                ✕
              </button>
            </div>

            <div className="map-container">
              <img src="/mapa_tec.png" alt="Mapa Campus" className="campus-map" />
              {ubicacionesData.map((u) => (
                <button
                  key={u.id}
                  className="map-button"
                  style={{ top: u.posicionMapa.top, left: u.posicionMapa.left }}
                  onClick={() => handleMapButtonClick(u.id)}
                >
                  {u.id}
                </button>
              ))}
            </div>

            <p className="map-caption">Mapa interactivo del campus universitario</p>
          </div>
        </>
      )}
    </div>
  );
}

/* ====================================
   Nota:
   - Ambos componentes están listos para exportarse desde un solo archivo.
   - Puedes importarlos individualmente así:
       import { Administrativas, Ubicaciones } from "./TuArchivoCombinado";
   ==================================== */
